<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../config/db.php';require_once __DIR__.'/../../includes/audit.php';
if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location:index.php');exit;}verify_csrf();
requireModulePermission('supplier_payments','create');
try{$sid=(int)($_POST['supplier_id']??0);$amount=(float)($_POST['amount']??0);$method=(string)($_POST['payment_method']??'Cash');$ref=trim((string)($_POST['transaction_reference']??''));$notes=trim((string)($_POST['notes']??''));
if(!in_array($method,['Cash','M-Pesa','Bank','Cheque','Other'],true))throw new RuntimeException('Invalid payment method.');
if($method==='M-Pesa'&&$ref==='')throw new RuntimeException('Enter the M-PESA transaction reference after making the payment.');
$conn->beginTransaction();
$s=$conn->prepare("SELECT * FROM suppliers WHERE id=? AND status='Active' FOR UPDATE");$s->execute([$sid]);$sup=$s->fetch();if(!$sup)throw new RuntimeException('Supplier not found or inactive.');if($amount<=0||$amount>(float)$sup['balance']+.001)throw new RuntimeException('Payment exceeds supplier payable balance.');
$receipt='TMP-'.strtoupper(bin2hex(random_bytes(8)));
$hasCashShiftColumn=(bool)$conn->query("SHOW COLUMNS FROM supplier_payments LIKE 'cash_shift_id'")->fetch();if($hasCashShiftColumn){$cashShiftId=null;if($method==='Cash'){$shiftQ=$conn->prepare("SELECT id FROM cash_shifts WHERE user_id=? AND status='Open' ORDER BY id DESC LIMIT 1");$shiftQ->execute([(int)$_SESSION['user_id']]);$cashShiftId=$shiftQ->fetchColumn()?:null;if(!$cashShiftId&&hasModulePermission('cash_management','create'))throw new RuntimeException('Open your cashier shift before making a cash supplier payment.');}$s=$conn->prepare("INSERT INTO supplier_payments(receipt_number,supplier_id,user_id,amount,payment_method,transaction_reference,payment_date,notes,cash_shift_id) VALUES(?,?,?,?,?,?,?,?,?)");$s->execute([$receipt,$sid,$_SESSION['user_id'],$amount,$method,$ref?:null,date('Y-m-d H:i:s'),$notes?:null,$cashShiftId]);}else{$s=$conn->prepare("INSERT INTO supplier_payments(receipt_number,supplier_id,user_id,amount,payment_method,transaction_reference,payment_date,notes) VALUES(?,?,?,?,?,?,?,?)");$s->execute([$receipt,$sid,$_SESSION['user_id'],$amount,$method,$ref?:null,date('Y-m-d H:i:s'),$notes?:null]);}$paymentId=(int)$conn->lastInsertId();$receipt='SP-'.date('ymd').'-'.str_pad((string)$paymentId,5,'0',STR_PAD_LEFT);$conn->prepare("UPDATE supplier_payments SET receipt_number=? WHERE id=?")->execute([$receipt,$paymentId]);$s=$conn->prepare("UPDATE suppliers SET balance=GREATEST(0,balance-?) WHERE id=?");$s->execute([$amount,$sid]);recordAuditEvent($conn,'Pay','supplier_payments','Recorded supplier payment '.$receipt.' of KES '.number_format($amount,2),'supplier_payment',$paymentId,null,['supplier_id'=>$sid,'amount'=>$amount,'payment_method'=>$method,'reference'=>$ref?:null]);$conn->commit();$_SESSION['supplier_payment_flash']='Supplier payment '.$receipt.' recorded successfully.';}catch(Throwable $e){if($conn->inTransaction())$conn->rollBack();$_SESSION['supplier_payment_flash']='Payment failed: '.$e->getMessage();}header('Location:index.php');exit;